const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

const FIRST_INSURANCE_SURCHARGE = 0.1;

interface Item {
  type: string;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

const quotePremium = (items: Item[]): number => {
  let total = 0;
  for (const item of items) {
    const base = BASE_PREMIUMS[item.type];
    total += base + base * FIRST_INSURANCE_SURCHARGE;
  }
  return Math.ceil(total + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => {
  const results = scenario.steps.map((step) => ({ premium: quotePremium(step.items) }));
  return { results };
};

