toolUseResult.originalFile:
const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;
const COMPONENT_TYPES = new Set(["rune"]);

const FIRST_INSURANCE_SURCHARGE = 0.1;

interface Item {
  type: string;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

interface QuoteResult {
  premium: number;
}

interface ScenarioResult {
  results: QuoteResult[];
}

const componentGroupBase = (count: number): number =>
  count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : count * COMPONENT_BASE_PREMIUM;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const itemBasePremiums = (items: Item[]): number[] => {
  const mainItems = items.filter((item) => !COMPONENT_TYPES.has(item.type));
  const components = items.filter((item) => COMPONENT_TYPES.has(item.type));

  const mainBases = mainItems.map((item) => BASE_PREMIUMS[item.type]);
  const componentBases = [...countByType(components).values()].map(
    componentGroupBase,
  );

  return [...mainBases, ...componentBases];
};

const quotePremium = (items: Item[]): number => {
  const bases = itemBasePremiums(items);
  const itemsTotal = bases.reduce(
    (sum, base) => sum + base + base * FIRST_INSURANCE_SURCHARGE,
    0,
  );
  return Math.ceil(itemsTotal + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  }));
  return { results };
};

