  const fractions: number[] = [];
  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) fractions.push(LOYALTY_DISCOUNT);
  if (isFollowUp) fractions.push(FOLLOWUP_CONTRACT_DISCOUNT);
  return fractions;
};

